  for aliases in select value from jsonb_array_elements('[["strawberry","فراولة","فراوله","strawberries","ستروبري","ستراوبري"],["cola","كولا","كوكاكولا","كوكوكولا","كوكا كولا","كوكو كولا","coca cola","coca-cola","cocacola","cococola"],["blueberry","توت ازرق","blueberries","بلوبيري","بلو بيري","توت أزرق"],["raspberry","توت العليق","raspberries","رازبيري","راسبيري"],["cherry","كرز","cherries","تشيري"],["chocolate","شوكولاتة","شوكولاته","شوكلاته","شوكلاتة","شوكولاطة","جوكلت","چوكلت","تشوكلت"],["caramel","كراميل","كاراميل"],["peach","خوخ","peaches"],["mango","مانجو","منجا","مانجا"],["pineapple","اناناس","أناناس"],["orange","برتقال"],["lemon","ليمون"],["jasmine","ياسمين"],["honey","عسل"],["banana","موز","banane","バナナ","plátano","香蕉"],["hazelnut","بندق","هازلنت","هازلنات","hazelnuts"],["almond","لوز","almonds"],["floral","زهور","زهري","florals"],["fruity","فواكه","fruits","fruit"],["citrus","حمضيات"],["cinnamon","قرفة","قرفه","دارسين"],["vanilla","فانيلا","فانيليا","ڤانيلا"],["passion fruit","باشن فروت","باشنفروت","فاكهة العاطفة","passionfruit"],["pear","إجاص","كمثرى"],["cardamom","هيل","هال"],["pistachio","فستق","بستاشيو","بيستاشيو"],["coconut","جوز الهند","جوزالهند","كوكونت","كوكونوت","كوكونات","كوكونن"],["cocoa","كاكاو","cacao","ككاو"],["wine","نبيذ","واين","winey","winy","wine-like","نبيذي"],["whisky","ويسكي","whiskey","وسكي"],["tea","شاي"],["cashew","كاجو"],["sugar","سكر"],["allspice","بهار حلو"],["amaretto","أماريتو"],["barley tea","شاي الشعير"],["biscuits","بسكويت","cookies"],["blackberries","توت أسود","blackberry"],["butter biscuit","بسكويت بالزبدة"],["butterscotch","كراميل بالزبدة"],["candied almond","لوز محلّى"],["candied lemon","ليمون محلّى"],["cane sugar","سكر القصب"],["cashew butter","زبدة الكاجو"],["cherry filled doughnut","دونات بحشوة الكرز"],["chocolate fudge","فدج الشوكولاتة"],["chocolate milk","حليب بالشوكولاتة"],["clean","واضحة"],["clementine","كلمنتينا"],["creamy white chocolate","شوكولاتة بيضاء كريمية"],["currants","كشمش","currant"],["dark grape","عنب داكن"],["dried berries","توت مجفف"],["earl grey","شاي إيرل غراي"],["fig","تين"],["grape soda","مشروب عنب غازي"],["heavy chocolate","شوكولاتة كثيفة"],["honeycomb","قرص العسل"],["honeydew","شمام عسلي"],["honeysuckle","زهرة العسلة"],["juicy & citrus finish","قوام عصيري ونهاية حمضية"],["key lime","لايم","lime"],["kumquat","كمكوات"],["lime curd","كريمة اللايم"],["lotus biscuit","بسكويت لوتس"],["malt","شعير"],["mandarin","يوسفي","mandarine","tangerine"],["maple","قيقب"],["maple syrup","شراب القيقب"],["matcha","ماتشا"],["melon","شمام","cantaloupe"],["mulled wine","نبيذ متبّل"],["mulling spice","توابل دافئة"],["myrtle liquor","مشروب الآس"],["panela","سكر قصب غير مكرر"],["peanut butter","زبدة الفول السوداني"],["peanut","فول سوداني","peanuts"],["pecan","بيكان"],["pink grapefruit","جريب فروت وردي"],["raspberry candy","حلوى توت العليق"],["raw honey","عسل خام"],["red grape","عنب أحمر","red grapes"],["red wine","نبيذ أحمر"],["redcurrant","كشمش أحمر","red currant","red currants","redcurrants"],["refined","رقيقة"],["rhubarb","راوند"],["ripe fruits","فواكه ناضجة"],["ripe orange","برتقال ناضج"],["roasted almonds","لوز محمص"],["roasted macadamia","مكاديميا محمصة"],["round","متوازنة"],["silky","حريرية"],["spearmint","نعناع"],["spices","توابل","spice"],["stone fruits","فواكه ذات نواة","stonefruit","stone fruit"],["sugarcane","قصب السكر","sugar cane"],["sweet berries","توت حلو"],["sweet blood orange","برتقال أحمر حلو"],["sweet tea","شاي حلو"],["tart apple","تفاح حامض"],["thick & syrupy","قوام كثيف"],["tropical fruits","فواكه استوائية"],["tropical fruit","فاكهة استوائية"],["vanilla cake","كيك الفانيلا"],["vanilla malt","شعير بالفانيلا"],["violet","بنفسج"],["waffle","وافل"],["white florals","زهور بيضاء"],["white grape","عنب أبيض","white grapes"],["white wine","نبيذ أبيض"],["white chocolate","شوكولاتة بيضاء"],["white peach","خوخ أبيض"],["burnt sugar","سكر محروق"],["dried cherry","كرز مجفف"],["dried apricot","مشمش مجفف"],["orange marmalade","مربى البرتقال"],["black cherry","كرز أسود"],["nutmeg","جوزة الطيب"],["marzipan","مرزبان"],["sultana","زبيب سلطاني"],["bitter orange","برتقال مر"],["miso caramel","كراميل الميسو"],["star anise","يانسون نجمي"],["kiwi","كيوي"],["berries jam","مربى توت"],["grape yoghurt","زبادي العنب"],["winegum","حلوى فاكهة"],["peach iced tea","شاي خوخ مثلج"],["jammy berries","توت بقوام مربى"],["sweet candy","حلوى"],["winey fruitiness","فاكهة مخمّرة"],["candy-like finish","نهاية حلوة"],["slight floral","لمسة زهرية"],["milk chocolate","شوكولاتة بالحليب"],["dark chocolate","شوكولاتة داكنة"],["nutty","مكسرات","nuts"],["walnut","جوز"],["grapefruit","جريب فروت"],["bergamot","برغموت"],["rose","ورد"],["hibiscus","كركديه"],["apricot","مشمش"],["toffee","توفي"],["brown sugar","سكر بني"],["berry","توت","berries"],["apple","تفاح"],["red apple","تفاح أحمر"],["green apple","تفاح أخضر"],["plum","برقوق"],["grape","عنب","grapes"],["raisin","زبيب","raisins"],["lavender","لافندر"],["chamomile","بابونج"],["black tea","شاي أسود"],["yellow plum","برقوق أصفر"],["dates","تمر"],["cloves","قرنفل"],["lychee","ليتشي"],["pomegranate","رمان"],["dried fig","تين مجفف"],["red berries","توت أحمر","red berry"],["mixed berries","توت مشكّل"],["black berries","توت داكن"],["almond cream","كريمة اللوز"],["blood orange","برتقال أحمر"],["nectarine","نكتارين"],["lemongrass","عشبة الليمون"],["dried fruit","فواكه مجففة","dried fruits"],["blackcurrant","كشمش أسود","black currant","black currants","blackcurrants"],["blueberry pie","فطيرة التوت الأزرق"],["candied pecan","بيكان مُحلّى"],["roasted walnuts","جوز محمّص"],["cacao nibs","قطع الكاكاو"],["candied walnuts","جوز مُحلّى"],["liquorice","عرق السوس"],["molasses","دبس"],["maraschino cherries","كرز ماراشينو"],["fruit-smoked","فواكه مع لمسة دخان"],["nougat","نوجا"],["praline","برالين"],["maltesers","مالتيزرز"],["sweet","حلوة"],["elegant","أنيقة"],["botanical","نباتية"],["sweet citrus","حمضيات حلوة"],["orange zest","قشر البرتقال"],["beeswax","شمع العسل"],["yellow peach","خوخ أصفر"],["chocolate","شوكولاتة","شوكولاته","شوكلاته","شوكلاتة","شوكولاطة","جوكلت","چوكلت","تشوكلت","cocoa","كاكاو","cacao","ككاو"]]'::jsonb) loop
    canonical:=aliases->>0;
    for alias in select value from jsonb_array_elements_text(aliases) loop
      if not public.recipe_discovery_matches(public.recipe_discovery_search_text(canonical),alias)
        or not public.recipe_discovery_matches(public.recipe_discovery_search_text(alias),canonical)
        then raise exception 'Flavor alias differs: % / %',canonical,alias; end if;
      if public.recipe_discovery_matches(public.recipe_discovery_search_text(canonical),alias||' unknown_brand_fixture')
        then raise exception 'Unknown constraint dropped: %',alias; end if;
    end loop;
  end loop;
  for source,alias in select * from (values
    ('Chocolate coconut','كوكاكولا'),('Chocolate','cola'),('Winegum','واين'),
    ('Walnut coffee from India','جوز الهند'),('White wine','red wine'),
    ('White chocolate','dark chocolate'),('Cola','كوكاكولا فراولة'),('Cola', $literal$كوكاكولا %') OR true --$literal$)
  ) cases(source,alias) loop
    if public.recipe_discovery_matches(public.recipe_discovery_search_text(source),alias)
      then raise exception 'Unrelated source matched: % / %',source,alias; end if;
  end loop;
  if not public.recipe_discovery_matches(public.recipe_discovery_search_text('Cola wine'),'كوكاكولا واين')
    or not public.recipe_discovery_matches(public.recipe_discovery_search_text('Cola cola'),'كوكاكولا كوكوكولا')
    then raise exception 'Adjacent aliases were not normalized'; end if;
  if has_function_privilege('anon','private.refresh_recipe_search_documents(uuid[])','EXECUTE')
    or has_table_privilege('anon','public.recipe_search_documents','UPDATE')
    then raise exception 'Guest can mutate the derived index'; end if;
end $tests$;


select private.refresh_recipe_search_documents(null::uuid[]);
